-- 📚 꼭집 주거 사전 — 총자산 1.08억 · 자동차 보유 불허 · 행복주택 대학생 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.3초 · 결과:
-- {"n": 12, "by_std": {"행복주택": 12}, "all_asset_anns": 203, "ex": ["20648_1_경기도_광명시", "20647_1_경기도_광명시", "2015122300020858", "2015122300020854"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('n',(select count(distinct announcement_id) from e where asset_limit=108000000 and car_limit is null),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit=108000000 and car_limit is null group by 1)q),'all_asset_anns',(select count(distinct announcement_id) from e where asset_limit is not null),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=108000000 and car_limit is null order by 1 desc limit 4)q))j;
